WITH parsed AS (SELECT id, host, level, status_code, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier FROM app_logs WHERE level = 'INFO') SELECT id, host, level, status_code, tier, SUM(status_code) OVER (PARTITION BY level ORDER BY status_code, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) last4_sum_status_code, COUNT(status_code) OVER (PARTITION BY level ORDER BY status_code, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) last4_count_status_code, MIN(status_code) OVER (PARTITION BY level ORDER BY status_code, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) last4_min_status_code, ROUND(status_code / SUM(status_code) OVER (PARTITION BY level, tier), 4) status_code_share FROM parsed
